#!/usr/bin/env python3
import sys, os, re, io, gzip, json, datetime as dt
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

FACT = {'kg': Decimal(1), 'lb': Decimal('0.45392'), 'oz': Decimal('0.02837'), 'g': Decimal('0.001')}
PRIORITY = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'harbor': 'iso', 'west': 'DD.MM.YYYY'}
BASE_UNIT = {'east': 'kg', 'river': 'kg', 'west': 'kg', 'harbor': 'kg', 'lakeside': 'kg',
             'north': 'kg', 'central': 'kg'}
DELIM = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
}
HARBOR_ST = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
FW_ST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def read_bytes(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    m = re.search(rb'^#\s*charset\s*:\s*([A-Za-z0-9_.\-]+)', b[:2000], re.M)
    enc = m.group(1).decode() if m else 'utf-8'
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode('utf-8', 'replace')


def norm_id(s):
    m = re.search(r'(\d+)', s)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', s.strip().lower())


def norm_type(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') and s not in ('',):
        return 'correction'
    if s.startswith('a'):
        return 'correction'
    return 'new'


def parse_date(v, form):
    v = v.strip()
    if 'T' in v or (' ' in v and ':' in v):
        d = dt.datetime.fromisoformat(v.replace(' ', 'T', 1) if 'T' not in v else v)
        if d.tzinfo is not None:
            d = d.astimezone(dt.timezone.utc)
        return d.date()
    f = form.strip()
    fl = f.lower()
    m = re.fullmatch(r'(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})', v)
    if m:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    if fl == 'serial':
        return dt.date(1899, 12, 31) + dt.timedelta(days=int(float(v)))
    nums = re.findall(r'\d+', v)
    if fl in ('iso', 'ymd', 'yyyy-mm-dd'):
        if len(nums) == 1 and len(nums[0]) == 8:
            return dt.date(int(nums[0][:4]), int(nums[0][4:6]), int(nums[0][6:]))
        return dt.date(int(nums[0]), int(nums[1]), int(nums[2]))
    if fl in ('dmy', 'dd/mm/yyyy', 'dd.mm.yyyy', 'dd-mm-yyyy'):
        return dt.date(int(nums[2]), int(nums[1]), int(nums[0]))
    if fl in ('mm/dd/yyyy', 'mdy'):
        return dt.date(int(nums[2]), int(nums[0]), int(nums[1]))
    if fl == 'yyyyddd':
        return dt.date(int(nums[0][:4]), 1, 1) + dt.timedelta(days=int(nums[0][4:]) - 1)
    if fl == 'yyyymmdd':
        return dt.date(int(nums[0][:4]), int(nums[0][4:6]), int(nums[0][6:]))
    # fallback by shape
    if len(nums[0]) == 4:
        return dt.date(int(nums[0]), int(nums[1]), int(nums[2]))
    return dt.date(int(nums[2]), int(nums[1]), int(nums[0]))


def parse_weight(s, unit, decimal_comma=False):
    """returns kg Decimal. s may carry a unit suffix."""
    s = s.strip()
    m = re.fullmatch(r'([-+0-9.,\s]+?)\s*([A-Za-z]+)?', s)
    if not m:
        raise ValueError(s)
    num, u = m.group(1), m.group(2)
    if u:
        unit = u.lower()
    num = num.replace(' ', '')
    if decimal_comma:
        num = num.replace('.', '').replace(',', '.')
    else:
        num = num.replace(',', '')
    return Decimal(num) * FACT[unit]


def split_records_text(text):
    """yield logical lines (CSV-style quote-aware) with flag whether it is a comment"""
    lines = text.split('\n')
    i = 0
    n = len(lines)
    while i < n:
        l = lines[i].rstrip('\r')
        i += 1
        if l.strip() == '':
            continue
        if l.startswith('#'):
            yield l, True
            continue
        while l.count('"') % 2 == 1 and i < n:
            l += '\n' + lines[i].rstrip('\r')
            i += 1
        yield l, False


def csv_split(line, delim):
    if delim != ',':
        return line.split(delim)
    out = []
    cur = []
    inq = False
    i = 0
    L = len(line)
    while i < L:
        c = line[i]
        if inq:
            if c == '"':
                if i + 1 < L and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    inq = False
            else:
                cur.append(c)
        else:
            if c == '"':
                inq = True
            elif c == ',':
                out.append(''.join(cur))
                cur = []
            else:
                cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out


def parse_directive(l):
    m = re.match(r'#\s*([A-Za-z][A-Za-z \-_]*?)\s*:\s*(.*)$', l)
    if not m:
        return None
    return re.sub(r'\s+', ' ', m.group(1).strip().lower()), m.group(2).strip()


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    seq = None
    date_form = BASE_DATE[depot]
    unit = BASE_UNIT[depot]
    dcomma = depot == 'west'
    hdr = None
    recs = []
    for line, is_comment in split_records_text(text):
        if is_comment:
            if depot == 'harbor':
                m = re.search(r'seq\s*=\s*(\d+)', line)
                if m and seq is None:
                    seq = int(m.group(1))
            d = parse_directive(line)
            if d:
                k, v = d
                if k == 'seq':
                    seq = int(re.search(r'\d+', v).group())
                elif k in ('unit', 'weight unit'):
                    w = v.split()[0].lower() if v.split() else unit
                    if w in FACT:
                        unit = w
                    if 'decimal comma' in v.lower():
                        dcomma = True
                elif k in ('dates', 'date format', 'date', 'dateformat'):
                    date_form = v.split()[0] if v.split() else date_form
            continue
        f = csv_split(line, delim)
        low = [x.strip().lower() for x in f]
        if all(x in cols for x in low) and len(low) >= 2:
            hdr = low
            continue
        if hdr is None:
            continue
        row_unit = None
        if len(f) == len(hdr) + 1 and depot == 'east':
            gi = hdr.index('gross')
            if f[gi + 1].strip().lower() in FACT:
                row_unit = f[gi + 1].strip().lower()
                f = f[:gi + 1] + f[gi + 2:]
        if len(f) == len(hdr) + 1:
            for j, x in enumerate(f):
                if x.strip().lower() in FACT:
                    row_unit = x.strip().lower()
                    f = f[:j] + f[j + 1:]
                    break
        if len(f) != len(hdr):
            continue
        r = dict(zip(hdr, f))
        idc = r.get('id', r.get('ref', ''))
        if depot == 'harbor':
            typ = r.get('rec', '')
        else:
            typ = r.get('type', r.get('kind', r.get('t', r.get('typ', r.get('rec', '')))))
        if 'TOTAL' in idc.upper() or norm_id(idc) is None:
            continue
        if not re.match(r'\s*SH', idc, re.I):
            continue
        t = norm_type(typ)
        rec = {'id': norm_id(idc), 'type': t}
        if t != 'void':
            wu = row_unit or unit
            if depot == 'east':
                w = r['gross']
            elif depot == 'lakeside':
                w = r['gross_kg']; wu = 'kg'
            else:
                w = r['weight']
            rec['kg'] = parse_weight(w, wu, dcomma)
            dv = r.get('shipped', r.get('date'))
            rec['date'] = parse_date(dv, date_form)
            st = r.get('status', r.get('state'))
            st = HARBOR_ST.get(st.strip().upper(), st) if depot == 'harbor' else st
            rec['status'] = norm_status(st)
        recs.append(rec)
    return seq, recs


FW = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), date=(10, 17), w=(17, 25), st=(25, 26), df='yyyyddd', mult=Decimal('0.001')),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), date=(10, 18), w=(18, 26), st=(26, 27), df='yyyymmdd', mult=Decimal('0.01')),
    'FW3': dict(len=41, id=(0, 9), date=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25), df='yyyyddd', mult=Decimal('0.1') * FACT['lb']),
}


def parse_south(text):
    seq = None
    layout = None
    recs = []
    bylen = {v['len']: k for k, v in FW.items()}
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.strip() == '' or line.startswith('\x0c') or 'LISTING' in line:
            continue
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                layout = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        lay = bylen.get(len(line), layout)
        if lay is None:
            continue
        sp = FW[lay]
        line = line.ljust(sp['len'])
        g = lambda k: line[sp[k][0]:sp[k][1]]
        t = norm_type(g('type'))
        idn = norm_id(g('id'))
        if idn is None:
            continue
        rec = {'id': idn, 'type': t}
        if t != 'void':
            wv = Decimal(int(g('w')))
            rec['kg'] = wv * sp['mult']
            rec['date'] = parse_date(g('date'), sp['df'])
            rec['status'] = FW_ST.get(g('st').strip().upper(), g('st').strip().lower())
        recs.append(rec)
    return seq, recs


def parse_north(text):
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta'] and seq is None:
                    seq = int(o['meta']['seq'])
                continue
            if 'id' not in o:
                continue
            t = norm_type(o.get('kind'))
            rec = {'id': norm_id(str(o['id'])), 'type': t}
            if t != 'void':
                wk = [k for k in o if k.startswith('weight')][0]
                u = wk.split('_', 1)[1].lower() if '_' in wk else 'kg'
                rec['kg'] = parse_weight(str(o[wk]), u)
                rec['date'] = parse_date(o['shipped_at'], 'iso')
                rec['status'] = norm_status(o['status'])
            recs.append(rec)
    return seq, recs


def parse_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    ru = (root.get('weight-unit') or 'kg').lower()
    recs = []
    for sh in root.iter('shipment'):
        t = norm_type(sh.get('type'))
        rec = {'id': norm_id(sh.get('id')), 'type': t}
        if t != 'void':
            we = sh.find('weight')
            u = (we.get('unit') or ru).lower()
            rec['kg'] = parse_weight(we.text, u)
            sv = sh.get('shipped')
            if sv is None:
                sv = sh.find('shipped').text
            rec['date'] = parse_date(sv, 'DD Mon YYYY')
            rec['status'] = norm_status(sh.find('status').text)
        recs.append(rec)
    return seq, recs


def parse_file(depot, path):
    b = read_bytes(path)
    if depot == 'central':
        return parse_central(b)
    if len(b) > 1 and b[1:2] == b'\x00' and b[:2] not in (b'\xff\xfe', b'\xfe\xff'):
        text = b.decode('utf-16-le')
    elif len(b) > 1 and b[0:1] == b'\x00' and b[:2] not in (b'\xff\xfe', b'\xfe\xff'):
        text = b.decode('utf-16-be')
    else:
        text = decode(b)
    if depot == 'south':
        return parse_south(text)
    if depot == 'north':
        return parse_north(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        if depot not in PRIORITY:
            continue
        files.setdefault(depot, []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exps = []
        for p in paths:
            seq, recs = parse_file(depot, p)
            exps.append((seq if seq is not None else -1, os.path.basename(p), recs))
        exps.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exps:
            for r in recs:
                k = r['id']
                if r['type'] == 'new':
                    if k in cur:
                        resends += 1
                    else:
                        cur[k] = r
                elif r['type'] == 'correction':
                    cur[k] = r
                    corrections += 1
                else:
                    cur.pop(k, None)
                    corrections += 1
        current[depot] = cur
    kept = {}
    handovers = 0
    seen = {}
    for depot in PRIORITY:
        for k, r in current.get(depot, {}).items():
            seen[k] = seen.get(k, 0) + 1
            if k not in kept:
                kept[k] = (depot, r)
    handovers = sum(1 for v in seen.values() if v > 1)
    dep = {d: [0, Decimal(0)] for d in files}
    mon = {}
    for k, (depot, r) in kept.items():
        if r['status'] not in ('delivered', 'delivered_late'):
            continue
        dep[depot][0] += 1
        dep[depot][1] += r['kg']
        m = '%04d-%02d' % (r['date'].year, r['date'].month)
        e = mon.setdefault(m, [0, Decimal(0)])
        e[0] += 1
        e[1] += r['kg']
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': v[0], 'total_kg': q(v[1])} for d, v in sorted(dep.items())},
        'months': {m: {'shipments': v[0], 'total_kg': q(v[1])} for m, v in sorted(mon.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(out, f, indent=2)


if __name__ == '__main__':
    main()
